function clean(v) {
  return v == null || v === '' ? null : String(v).trim().replace(/\s+/g, ' ');
}
function email(v) {
  return clean(v)?.toLowerCase() || null;
}
function name(v) {
  const s = clean(v);
  return s ? s.replace(/\b\w/g, c => c.toUpperCase()) : null;
}
return $input.all().map(item => {
  const r = item.json;
  return {json: {
    ...r,
    full_name: name(r.full_name || r.name),
    email: email(r.email),
    company: clean(r.company),
    role: clean(r.role),
    sources: Array.isArray(r.sources) ? r.sources : [],
    evidence: Array.isArray(r.evidence) ? r.evidence : [],
    verification_evidence: r.verification_evidence || {},
    issues: Array.isArray(r.issues) ? r.issues : []
  }};
});

const byEmail = new Map();
const noEmail = [];
let duplicateCount = 0;

for (const item of $input.all()) {
  const r = item.json;
  const email = r.email;

  if (!email) {
    noEmail.push(r);
    continue;
  }

  if (!byEmail.has(email)) {
    byEmail.set(email, {...r});
    continue;
  }

  duplicateCount++;
  const target = byEmail.get(email);

  for (const key of ['sources', 'evidence']) {
    target[key] = [...new Set([
      ...(target[key] || []), ...(r[key] || [])
    ])];
  }

  target.issues = target.issues || [];
  for (const key of ['full_name', 'company', 'role']) {
    if (target[key] && r[key] && target[key] !== r[key]) {
      target.issues.push(
        `Conflicting ${key}: ${target[key]} vs ${r[key]}`
      );
    } else if (!target[key] && r[key]) {
      target[key] = r[key];
    }
  }
  target.issues = [...new Set(target.issues)];
}

return [...byEmail.values(), ...noEmail].map(r => ({
  json: {...r, duplicate_count: duplicateCount}
}));

const r = $json;
const ev = r.verification_evidence || {};
const valid = !!r.email &&
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email);

const identity = !!ev.identity_supported;
const company = !!ev.company_supported;
const role = !!ev.role_supported;
const external = !!ev.external_source_found;

const contradictions = [
  ...(Array.isArray(ev.contradictions) ? ev.contradictions : []),
  ...(Array.isArray(r.issues) ? r.issues.filter(
    x => String(x).startsWith('Conflicting ')
  ) : [])
];
const uniqueContradictions = [...new Set(contradictions)];

const score =
  (valid ? 15 : 0) +
  (identity ? 20 : 0) +
  (company ? 25 : 0) +
  (role ? 25 : 0) +
  (external ? 10 : 0) +
  (uniqueContradictions.length ? 0 : 5);

const status = uniqueContradictions.length ? 'CONFLICT' :
  (score >= 90 && identity && company ? 'VERIFIED' :
  (score >= 50 ? 'PARTIALLY_VERIFIED' : 'UNVERIFIED'));

const issues = [...(Array.isArray(r.issues) ? r.issues : []),
  ...uniqueContradictions];

if (!valid) issues.push('Email missing or invalid');

const missing = ['full_name', 'email', 'company', 'role']
  .filter(k => !r[k]);
if (missing.length) issues.push('Missing fields: ' + missing.join(', '));
if (!external) issues.push('No external evidence found');

return {json: {
  ...r,
  email_valid: valid,
  identity_verified: identity,
  company_verified: company,
  role_verified: role,
  external_source_found: external,
  confidence_score: score,
  status,
  sources: [...new Set([
    ...(r.sources || []), ...(ev.sources || [])
  ])],
  issues: [...new Set(issues)]
}};

const out = [];

function addPerson(person, event) {
  if (!person || typeof person !== 'object') return;
  const email = String(person.email || '').trim().toLowerCase();
  if (!email) return;

  out.push({json: {
    full_name: person.displayName || person.name || null,
    email,
    company: person.company || null,
    role: person.role || null,
    meeting_title: event.summary || event.title || null,
    sources: ['Calendar'],
    evidence: [],
    verification_evidence: {}
  }});
}

for (const item of $input.all()) {
  const event = item.json;
  for (const person of (Array.isArray(event.attendees) ? event.attendees : [])) {
    addPerson(person, event);
  }
  if (event.organizer) addPerson(event.organizer, event);
}
return out;

const out = [];

function extract(value) {
  const found = [];
  function walk(v) {
    if (!v) return;
    if (Array.isArray(v)) {
      for (const x of v) walk(x);
      return;
    }
    if (typeof v === 'object') {
      const address = v.email || v.address;
      if (address && String(address).includes('@')) {
        found.push({
          email: String(address).trim().toLowerCase(),
          name: v.name || v.displayName || v.personal || null
        });
      } else {
        for (const x of Object.values(v)) walk(x);
      }
      return;
    }
    if (typeof v === 'string') {
      const re = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig;
      for (const match of v.matchAll(re)) {
        const email = match[0].toLowerCase();
        const prefix = v.slice(0, match.index);
        const name = prefix.replace(/[<("'\s,;:]+$/g, '').trim() || null;
        found.push({email, name});
      }
    }
  }
  walk(value);
  const seen = new Set();
  return found.filter(p => {
    if (seen.has(p.email)) return false;
    seen.add(p.email);
    return true;
  });
}

for (const item of $input.all()) {
  const message = item.json;
  const fields = [
    message.from, message.sender, message.to,
    message.cc, message.bcc,
    message.headers?.From, message.headers?.To,
    message.headers?.Cc
  ];

  for (const field of fields) {
    for (const person of extract(field)) {
      out.push({json: {
        full_name: person.name,
        email: person.email,
        company: null,
        role: null,
        meeting_title: message.subject || null,
        sources: ['Gmail'],
        evidence: [],
        verification_evidence: {}
      }});
    }
  }
}
return out;
